mapper.update:
update transaction_flow set is_unapproved = true,version = version + 1,
update_time = #{updateTime}, update_user_id = #{updateUserId}, update_user_name = #{updateUserName}
where id = #{id} and version = #{version} and is_deleted = false

mapper.select:
SELECT t.id,t.trade_time, t.bill_date, t.source_type, t.source_code, t.operation_mode, t.sku_id, t.sku_no, t.warehouse_location, t.warehouse_id, t.warehouse_name, t.org_id, t.dict_inventory_status as inventory_status, t.qty, t.cur_inventory_qty as after_qty, t.instock_batch_date FROM transaction_flow t WHERE t.is_deleted = false AND t.warehouse_id = #{params.warehouseId} AND t.org_id = #{params.orgId} AND t.sku_id = #{params.skuId}
and t.source_code = #{params.sourceCode}
and t.operation_mode in
#{item}
and t.dict_inventory_status in
#{item}
and t.bill_date >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > t.bill_date
order by t.trade_time desc,t.id desc

SELECT t.id,t.trade_time, t.bill_date, t.source_type, t.source_code, t.operation_mode, t.sku_id, t.sku_no, t.warehouse_location, t.warehouse_id, t.warehouse_name, t.org_id, t.dict_inventory_status as inventory_status, t.qty, t.cur_inventory_qty as after_qty, t.instock_batch_date, pi.spu_no, ps.sale_state FROM transaction_flow t left join product_detail pd on pd.id = t.sku_id left join product_info pi on pd.product_id = pi.id left join product_sale ps on ps.sku_id = pd.id WHERE t.is_deleted = false
and t.dict_biz_type in ('02','03','04','05','07','08','09','11','12','17','18','19','20','23','24','26')
and t.sku_no in
#{item}
and t.source_code ilike concat('%', #{params.sourceCode} ,'%')
and t.source_type in
#{item}
and pi.spu_no in
#{item}
and ps.sale_state in
#{item}
and t.warehouse_id in
#{item}
and t.org_id in
#{item}
and t.trade_time >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > t.trade_time
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
t.create_time desc

SELECT t.id,t.trade_time, t.bill_date, t.source_type, t.source_code, t.operation_mode, t.sku_id, t.sku_no, t.warehouse_location, t.warehouse_id, t.warehouse_name, t.org_id, t.dict_inventory_status as inventory_status, t.qty, t.cur_inventory_qty as after_qty, t.instock_batch_date, pi.spu_no, ps.sale_state FROM transaction_flow t left join product_detail pd on pd.id = t.sku_id left join product_info pi on pd.product_id = pi.id left join product_sale ps on ps.sku_id = pd.id WHERE t.is_deleted = false
and t.dict_biz_type in ('02','03','04','05','07','08','09','11','12','17','18','19','20','23','24','26')
and t.id in
#{item}
and t.sku_no in
#{item}
and t.source_code ilike concat('%', #{params.sourceCode} ,'%')
and t.source_type in
#{item}
and pi.spu_no in
#{item}
and ps.sale_state in
#{item}
and t.warehouse_id in
#{item}
and t.org_id in
#{item}
and t.trade_time >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > t.trade_time
${params.permissionSql}
ORDER BY t.create_time desc

select m.warehouse_id,m.warehouse_name,m.sku_id,m.sku_no,m.spu_no, m.purchase_instock_qty,m.inventory_profit_instock_qty,m.other_instock_qty,m.sale_return_qty,m.transfer_instock_qty,m.machine_instock_qty, m.purchase_return_qty,m.transfer_outstock_qty,m.sale_outstock_qty,m.other_outstock_qty,m.inventory_loss_outstock_qty,m.machine_outstock_qty from ( select tf.warehouse_id,max(tf.warehouse_name) as warehouse_name,tf.sku_id,max(tf.sku_no) as sku_no ,max(pi.spu_no) as spu_no, sum(case when tf.dict_biz_type in('02','03') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as purchase_instock_qty, -- 采购入库 sum(case when tf.dict_biz_type in ('13') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as inventory_profit_instock_qty, -- 盘盈入库 sum(case when tf.dict_biz_type in ('19') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as other_instock_qty, -- 其他入库 sum(case when tf.dict_biz_type in ('12') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as sale_return_qty, -- 销售退货入库 sum(case when tf.dict_biz_type in ('07','26') and tf.dict_inventory_status = 'usable' then tf.qty -- 直接调拨单（新增）目的仓可用增加；直接调拨单（调拨申请单下推）目的仓可用增加 when tf.dict_biz_type in ('09') and tf.dict_inventory_status = 'usable' then tf.qty else 0 -- 分步式调拨调入目的仓可用增加 end) as transfer_instock_qty, -- 调拨入库 sum(case when tf.dict_biz_type in ('17','24') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as machine_instock_qty, -- 加工入库
sum(case when tf.dict_biz_type in('04','05') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as purchase_return_qty, -- 采购退货出库 sum(case when tf.dict_biz_type in('07') and tf.dict_inventory_status = 'usable' then tf.qty -- 直接调拨单（新增）当前仓可用减少； when tf.dict_biz_type in('26','08') and tf.dict_inventory_status = 'frozen' then tf.qty else 0 end) as -- 直接调拨单（调拨申请单下推），分布式调拨调出当前仓冻结减少 transfer_outstock_qty, -- 调拨出库（分布式调拨出库单，冻结减少） sum(case when tf.dict_biz_type in('11') and tf.dict_inventory_status = 'frozen' then tf.qty else 0 end) as sale_outstock_qty, -- 销售出库（销售出库，冻结减少） sum(case when tf.dict_biz_type in('20') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as other_outstock_qty, -- 其他出库 sum(case when tf.dict_biz_type in('14') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as inventory_loss_outstock_qty, -- 盘亏出库 sum(case when tf.dict_biz_type in('18','23') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as machine_outstock_qty -- 加工出库 from transaction_flow tf left join product_detail pd on pd.id = tf.sku_id left join product_info pi on pd.product_id = pi.id
tf.is_deleted = false
and tf.sku_no in
#{item}
and pi.spu_no in
#{item}
and tf.warehouse_id in
#{item}
and tf.trade_time >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > tf.trade_time
${params.permissionSql}
group by tf.warehouse_id, tf.sku_id ) m ORDER BY m.warehouse_name asc,m.sku_no asc

select m.warehouse_id,m.warehouse_name,m.sku_id,m.sku_no,m.spu_no, m.purchase_instock_qty,m.inventory_profit_instock_qty,m.other_instock_qty,m.sale_return_qty,m.transfer_instock_qty,m.machine_instock_qty, m.purchase_return_qty,m.transfer_outstock_qty,m.sale_outstock_qty,m.other_outstock_qty,m.inventory_loss_outstock_qty,m.machine_outstock_qty from ( select tf.warehouse_id,max(tf.warehouse_name) as warehouse_name,tf.sku_id,max(tf.sku_no) as sku_no ,max(pi.spu_no) as spu_no, sum(case when tf.dict_biz_type in('02','03') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as purchase_instock_qty, -- 采购入库 sum(case when tf.dict_biz_type in ('13') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as inventory_profit_instock_qty, -- 盘盈入库 sum(case when tf.dict_biz_type in ('19') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as other_instock_qty, -- 其他入库 sum(case when tf.dict_biz_type in ('12') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as sale_return_qty, -- 销售退货入库 sum(case when tf.dict_biz_type in ('07','26') and tf.dict_inventory_status = 'usable' then tf.qty when tf.dict_biz_type in ('09') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as transfer_instock_qty, -- 调拨入库 sum(case when tf.dict_biz_type in ('17','24') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as machine_instock_qty, -- 加工入库
sum(case when tf.dict_biz_type in('04','05') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as purchase_return_qty, -- 采购退货出库 sum(case when tf.dict_biz_type in('07') and tf.dict_inventory_status = 'usable' then tf.qty when tf.dict_biz_type in('26','08') and tf.dict_inventory_status = 'frozen' then tf.qty else 0 end) as transfer_outstock_qty, -- 调拨出库（分布式调拨出库单，冻结减少） sum(case when tf.dict_biz_type in('11') and tf.dict_inventory_status = 'frozen' then tf.qty else 0 end) as sale_outstock_qty, -- 销售出库（销售出库，冻结减少） sum(case when tf.dict_biz_type in('20') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as other_outstock_qty, -- 其他出库 sum(case when tf.dict_biz_type in('14') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as inventory_loss_outstock_qty, -- 盘亏出库 sum(case when tf.dict_biz_type in('18','23') and tf.dict_inventory_status = 'usable' then tf.qty else 0 end) as machine_outstock_qty -- 加工出库 from transaction_flow tf left join product_detail pd on pd.id = tf.sku_id left join product_info pi on pd.product_id = pi.id
tf.is_deleted = false
and tf.sku_no in
#{item}
and pi.spu_no in
#{item}
and tf.warehouse_id in
#{item}
and tf.trade_time >= #{params.dateList[0]} and (#{params.dateList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > tf.trade_time
${params.permissionSql}
group by tf.warehouse_id, tf.sku_id ) m ORDER BY m.warehouse_name asc,m.sku_no asc
